func TestFilesService_AddUpload(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.Header.Get("X-Test"); got != "1" {
			t.Fatalf("unexpected header X-Test: %q", got)
		}
		if err := r.ParseMultipartForm(1 << 20); err != nil {
			t.Fatalf("parse multipart form: %v", err)
		}
		if got := r.Form.Get("deal_id"); got != "42" {
			t.Fatalf("unexpected deal_id: %q", got)
		}
		if got := r.Form.Get("lead_id"); got != "abc-123" {
			t.Fatalf("unexpected lead_id: %q", got)
		}
		file, header, err := r.FormFile("file")
		if err != nil {
			t.Fatalf("form file: %v", err)
		}
		defer file.Close()
		if header.Filename != "recording.mp3" {
			t.Fatalf("unexpected file name: %q", header.Filename)
		}
		content, err := io.ReadAll(file)
		if err != nil {
			t.Fatalf("read file content: %v", err)
		}
		if string(content) != "recording-bytes" {
			t.Fatalf("unexpected file content: %q", string(content))
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"recording.mp3"}}`))
	})

	file, err := client.Files.AddUpload(
		context.Background(),
		"recording.mp3",
		strings.NewReader("recording-bytes"),
		WithUploadDealID(DealID(42)),
		WithUploadLeadID(LeadID("abc-123")),
		WithUploadRequestOptions(pipedrive.WithHeader("X-Test", "1")),
	)
	if err != nil {
		t.Fatalf("AddUpload error: %v", err)
	}
	if file.ID != 12 || file.Name != "recording.mp3" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func TestFilesService_AddUpload_RetriesOn429(t *testing.T) {
	t.Parallel()

	var attempts int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		attempts++
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Errorf("read request body: %v", err)
		}
		if !strings.Contains(string(body), "recording-bytes") {
			t.Errorf("attempt %d: incomplete multipart body", attempts)
		}
		if attempts == 1 {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"success":false,"error":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":77,"name":"recording.mp3"}}`))
	}))
	defer srv.Close()

	cfg := pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts:     3,
			BaseDelay:       time.Millisecond,
			MaxDelay:        time.Millisecond,
			Jitter:          func(d time.Duration) time.Duration { return d },
			RetryAllMethods: true,
		},
	}
	client, err := NewClient(cfg)
	if err != nil {
		t.Fatalf("NewClient error: %v", err)
	}
	client.Raw, err = pipedrive.NewRawClient(srv.URL, pipedrive.NewHTTPClient(overrideBase(cfg, srv.URL)))
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	file, err := client.Files.AddUpload(context.Background(), "recording.mp3", strings.NewReader("recording-bytes"))
	if err != nil {
		t.Fatalf("AddUpload error: %v", err)
	}
	if file.ID != 77 {
		t.Fatalf("unexpected file: %#v", file)
	}
	if attempts != 2 {
		t.Fatalf("expected 2 attempts, got %d", attempts)
	}
}

func TestFilesService_AddUpload_RequiresFileNameAndContent(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		t.Fatalf("unexpected request")
	})

	if _, err := client.Files.AddUpload(context.Background(), "", strings.NewReader("x")); err == nil {
		t.Fatalf("expected error for empty file name")
	}
	if _, err := client.Files.AddUpload(context.Background(), "f.txt", nil); err == nil {
		t.Fatalf("expected error for nil content")
	}
}

